CREATE OR REPLACE DYNAMIC TABLE AGG.AGG_REVENUE_MONTH_TYPE_CUSTOMER_SEGMENT
  TARGET_LAG = '24 hours'
  WAREHOUSE  = WH_SEMANTIC_REFRESH
  COMMENT = 'Demand-driven aggregate of FCT_REVENUE at grain Date.FiscalYear, Date.MonthName, Date.Quarter, RevenueRecord.CustomerSegment, RevenueRecord.RevenueType, Date.MonthNumber; covers 75.98% of weighted demand (3 clusters); est. 480 rows; ~0.0167 credits/day'
AS
SELECT d1.FISCAL_YEAR,
       d1.MONTH_NAME,
       d1.QUARTER,
       f.CUSTOMER_SEGMENT,
       f.REVENUE_TYPE,
       d1.MONTH_NUMBER,
       SUM(f.AMOUNT) AS AMOUNT,
       SUM(f.KWH_SOLD) AS KWH_SOLD,
       SUM(f.REVENUE_PER_KWH) AS REVENUE_PER_KWH_SUM,
       COUNT(f.REVENUE_PER_KWH) AS REVENUE_PER_KWH_COUNT,
       COUNT(*) AS REVENUE_COUNT
FROM CORE.FCT_REVENUE f
JOIN CORE.DIM_DATE d1 ON f.DATE_KEY = d1.DATE_KEY
GROUP BY ALL;
